// Original analytic condensed material+geometric HVP and bounded Lanczos screen.
#define main original_solver_main
#include "solver.cpp"
#include <sstream>
#undef main
V hvp(const Model&m,const V&u,const V&old,const V&v){V out(m.N*3,0);for(size_t e=0;e<m.T;e++){size_t ids[4];for(int k=0;k<4;k++)ids[k]=3*m.ids[e*4+k];for(size_t r=0;r<m.R;r++){size_t ir=e*m.R+r,co=ir*4;double x[3]={m.dirs[4*r],m.dirs[4*r+1],m.dirs[4*r+2]},dx[3]={0,0,0};for(int k=0;k<4;k++)for(int d=0;d<3;d++){x[d]+=u[ids[k]+d]*m.C[co+k];dx[d]+=v[ids[k]+d]*m.C[co+k];}double L=std::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]),a[3]={x[0]/L,x[1]/L,x[2]/L},dl=a[0]*dx[0]+a[1]*dx[1]+a[2]*dx[2];Q q=response(L-1,old.empty()?0:old[ir],m.law);double w=15*m.vol[e]*m.dirs[4*r+3];for(int k=0;k<4;k++)for(int d=0;d<3;d++)out[ids[k]+d]+=w*m.C[co+k]*(q.k*dl*a[d]+q.t/L*(dx[d]-a[d]*dl));}}for(size_t i=0;i<out.size();i++)if(m.fixed[i/3])out[i]=0;return out;}
std::pair<double,double>eig(std::vector<V>A){int n=A.size();for(int it=0;it<20000;it++){int p=0,q=1;double best=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(std::abs(A[i][j])>best){best=std::abs(A[i][j]);p=i;q=j;}if(best<1e-11)break;double phi=.5*std::atan2(2*A[p][q],A[q][q]-A[p][p]),c=std::cos(phi),s=std::sin(phi),a=A[p][p],b=A[q][q],d=A[p][q];for(int k=0;k<n;k++)if(k!=p&&k!=q){double x=A[k][p],y=A[k][q];A[k][p]=A[p][k]=c*x-s*y;A[k][q]=A[q][k]=s*x+c*y;}A[p][p]=c*c*a-2*s*c*d+s*s*b;A[q][q]=s*s*a+2*s*c*d+c*c*b;A[p][q]=A[q][p]=0;}double lo=INFINITY,hi=-INFINITY;for(int i=0;i<n;i++){lo=std::min(lo,A[i][i]);hi=std::max(hi,A[i][i]);}return{lo,hi};}
V readv(const std::string&p,size_t n){std::ifstream f(p,std::ios::binary);V v(n);f.read((char*)v.data(),n*8);if(!f)throw std::runtime_error("Missing audit vector "+p);return v;}
int main(int argc,char**argv){try{if(argc<7)throw std::runtime_error("input u previous buck Y output");Model m(argv[1],{std::stod(argv[4]),std::stod(argv[5])});V u=readv(argv[2],m.N*3),old;if(std::stod(argv[5])>=0)old=readv(argv[3],m.T*m.R);size_t D=m.N*3;V q(D),prev(D,0);for(size_t i=0;i<D;i++)q[i]=m.fixed[i/3]?0:std::sin(i*.37)+std::cos(i*.13);double norm=std::sqrt(m.dot(q,q));for(auto&v:q)v/=norm;V first=q;std::vector<V>basis;V aa,bb;double beta=0;for(int k=0;k<32;k++){basis.push_back(q);V w=hvp(m,u,old,q);if(k)for(size_t i=0;i<D;i++)w[i]-=beta*prev[i];double alpha=m.dot(q,w);for(size_t i=0;i<D;i++)w[i]-=alpha*q[i];for(int pass=0;pass<2;pass++)for(const V&b:basis){double p=m.dot(b,w);for(size_t i=0;i<D;i++)w[i]-=p*b[i];}double b=std::sqrt(m.dot(w,w));aa.push_back(alpha);if(b<1e-12||k==31)break;bb.push_back(b);prev=q;for(size_t i=0;i<D;i++)q[i]=w[i]/b;beta=b;}
 std::vector<V>A(aa.size(),V(aa.size(),0));for(size_t i=0;i<aa.size();i++){A[i][i]=aa[i];if(i<bb.size())A[i][i+1]=A[i+1][i]=bb[i];}auto bounds=eig(A);V exact=hvp(m,u,old,first);std::vector<double>errors,fdMinJ;std::vector<bool>fdValid;for(double eps:{1e-4,1e-5,1e-6}){V plus=u,minus=u;for(size_t i=0;i<D;i++){plus[i]+=eps*first[i];minus[i]-=eps*first[i];}Eval a=m.eval(plus,old),b=m.eval(minus,old);double minimumJ=std::min(m.minJ(plus),m.minJ(minus));bool valid=std::isfinite(a.E)&&std::isfinite(b.E)&&std::isfinite(minimumJ)&&minimumJ>.05;double num=0,den=0;for(size_t i=0;i<D;i++)if(!m.fixed[i/3]){valid=valid&&std::isfinite(a.g[i])&&std::isfinite(b.g[i])&&std::isfinite(exact[i]);double v=(a.g[i]-b.g[i])/(2*eps);num+=(v-exact[i])*(v-exact[i]);den+=exact[i]*exact[i];}valid=valid&&std::isfinite(num)&&std::isfinite(den)&&den>0;double error=valid?std::sqrt(num/den):std::numeric_limits<double>::quiet_NaN();valid=valid&&std::isfinite(error);errors.push_back(error);fdValid.push_back(valid);fdMinJ.push_back(minimumJ);}
 auto jsonDouble=[](double x){if(!std::isfinite(x))return std::string("null");std::ostringstream text;text<<std::setprecision(17)<<x;return text.str();};std::ofstream out(argv[6]);out<<std::setprecision(17)<<"{\"lanczos_steps\":"<<aa.size()<<",\"min_ritz\":"<<bounds.first<<",\"max_ritz\":"<<bounds.second<<",\"resolved_negative_curvature\":"<<(bounds.first< -1e-7*std::max(1.,std::abs(bounds.second))?"true":"false")<<",\"analytic_hvp_fd_relative\":["<<(fdValid[0]?jsonDouble(errors[0]):"null")<<","<<(fdValid[1]?jsonDouble(errors[1]):"null")<<","<<(fdValid[2]?jsonDouble(errors[2]):"null")<<"],\"analytic_hvp_fd_valid\":["<<(fdValid[0]?"true":"false")<<","<<(fdValid[1]?"true":"false")<<","<<(fdValid[2]?"true":"false")<<"],\"analytic_hvp_fd_minJ\":["<<jsonDouble(fdMinJ[0])<<","<<jsonDouble(fdMinJ[1])<<","<<jsonDouble(fdMinJ[2])<<"],\"scope\":\"One seeded final-state restricted analytic-Hessian screen, not proof of stability or mesh convergence along trajectory\"}";std::cout<<"Ritz "<<bounds.first<<" "<<bounds.second<<" HVPerr "<<errors[1]<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
